const esc=x=>wording(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const get=async(path,opts={})=>{const r=await fetch(base+path,opts),v=await r.json();if(!r.ok)throw Error(typeof v.detail==='string'?v.detail:JSON.stringify(v.detail));return v;};
function coordinateFallback(source,schemeId,format){
 const rows=[];
 if(source==='station'){
  for(const st of stationRecord?.result?.stations||[])for(const setup of st.setups||[])for(const region of setup.measurement_regions||[])for(let i=0;i<(region.anchors||[]).length;i++){
   const p=region.anchors[i].position||[];rows.push({shot_id:`${st.id}/${setup.id} · setup region`,fai:region.number,point_name:`FAI${region.number}_anchor_${i+1}`,coordinate_status:'CAD_marker_only_no_MSOP_link',capture_image_status:'no_camera_exposure_pose_or_intrinsics',cad_world_xyz_mm:p,image_u_px:null,image_v_px:null,image_width_px:null,image_height_px:null,in_image:null,coordinate_authority:'CAD display coordinates; pixel projection unavailable for this Station / Setup'});
  }
 }else{
  const run=state?.run,roi=run?.design?.roi_px||[2400,2000],result=run?.result||{};let heads=result.heads||[];
  if(schemeId){const scheme=(result.integrated_schemes||[]).find(s=>s.id===schemeId),allowed=new Set((scheme?.stations||[]).flatMap(s=>s.head_ids||[]));heads=heads.filter(h=>allowed.has(h.id));}
  const tasks=new Map((state?.tasks||[]).map(t=>[Number(t.number),t]));
  for(const head of heads){const s=head.scene||{},[fw,fh]=s.fov_xy_mm||[],[w,h]=head.optics?.roi_px||roi;let atoms=head.coverage_atoms||[];
   if(!atoms.length)atoms=(head.fai_numbers||[]).flatMap(n=>(tasks.get(Number(n))?.anchors||[]).map((_,i)=>`${n}:${i}`));
   for(const atom of atoms){const [ns,is]=String(atom).split(':');const n=Number(ns),i=Number(is),point=tasks.get(n)?.anchors?.[i]?.position;if(!point)continue;let u=null,v=null,inside=false;
    if(s.target_mm&&s.basis_x&&s.basis_y&&fw&&fh){const d=point.map((x,k)=>x-s.target_mm[k]),x=d.reduce((sum,value,k)=>sum+value*s.basis_x[k],0),y=d.reduce((sum,value,k)=>sum+value*s.basis_y[k],0);u=(x/fw+.5)*w;v=(.5-y/fh)*h;inside=u>=0&&u<w&&v>=0&&v<h;}
    rows.push({shot_id:head.id,fai:n,point_name:`FAI${n}_anchor_${i+1}`,camera:head.camera,lens:head.lens,light:head.light,lighting_strategy:head.lighting_strategy,coordinate_status:'CAD_marker_only_no_MSOP_point_link',capture_image_status:u===null?'no_valid_projection':'virtual_projection_from_CAD',cad_world_xyz_mm:point,image_u_px:u===null?null:Number(u.toFixed(3)),image_v_px:v===null?null:Number(v.toFixed(3)),image_width_px:w,image_height_px:h,in_image:inside,coordinate_authority:'CAD display coordinates; source XYZ mapping unavailable in this fallback'});
   }
  }
 }
 if(format==='json')return JSON.stringify({coordinate_convention:{MSOP:'This browser fallback has no verified MSOP-to-CAD point map; source coordinates are omitted.',CAD:'CAD display frame in mm.',image:'Orthographic virtual CAD projection; not a sensor capture.'},rows},null,2);
 const fields=['shot_id','fai','point_name','camera','lens','light','lighting_strategy','coordinate_status','capture_image_status','cad_x_mm','cad_y_mm','cad_z_mm','image_u_px','image_v_px','image_width_px','image_height_px','in_image','coordinate_authority'];
 const cell=x=>{const s=String(x??'');return /[",\n\r]/.test(s)?`"${s.replaceAll('"','""')}"`:s;};
 return '\ufeff'+[fields.join(','),...rows.map(r=>{const p=r.cad_world_xyz_mm||[];return [r.shot_id,r.fai,r.point_name,r.camera,r.lens,r.light,r.lighting_strategy,r.coordinate_status,r.capture_image_status,p[0],p[1],p[2],r.image_u_px,r.image_v_px,r.image_width_px,r.image_height_px,r.in_image,r.coordinate_authority].map(cell).join(',');})].join('\r\n');
}
async function exportCoordinateReport(format,schemeId,source){
 const projectId=$('projects').value,query=new URLSearchParams({format});if(schemeId)query.set('scheme_id',schemeId);
 let blob;
 try{const response=await fetch(`${base}/projects/${projectId}/workflow/virtual-shots?${query}`);if(!response.ok)throw Error('坐标服务尚未重载');blob=await response.blob();}
 catch{const content=coordinateFallback(source,schemeId,format);blob=new Blob([content],{type:format==='csv'?'text/csv;charset=utf-8':'application/json;charset=utf-8'});notice('已导出当前方案坐标；此版本暂未提供MSOP点到CAD的逐点配准时，文件会明确标注未配准，MSOP源坐标不会被伪造。');}
 const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`oracle-${projectId}-coordinates.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-coordinate-export]');if(!button)return;event.preventDefault();void exportCoordinateReport(button.dataset.coordinateExport,button.dataset.schemeId||'',button.dataset.coordinateSource||'shots').catch(error);});
